function(container, apiUrl, tables) {
  const reportTypeRadios = container.querySelectorAll('input[name="report-type"]');
  const exportFormatRadios = container.querySelectorAll('input[name="export-format"]');
  const startDateInput = container.querySelector('input[name="start-date"]');
  const endDateInput = container.querySelector('input[name="end-date"]');
  const groupFilterSelect = container.querySelector('select[name="group-filter"]');
  const userSearchInput = container.querySelector('input[name="user-search"]');
  const userFilterSelect = container.querySelector('select[name="user-filter"]');
  const previewButton = container.querySelector('[data-testid="preview-button"]');
  const downloadButton = container.querySelector('[data-testid="download-button"]');
  const resetButton = container.querySelector('[data-testid="reset-button"]');
  const previewArea = container.querySelector('#preview-area');
  const historyTbody = container.querySelector('#history-tbody');
  const previewModal = container.querySelector('#preview-modal');
  const previewModalClose = container.querySelector('#preview-modal-close');
  const previewModalContent = container.querySelector('#preview-modal-content');
  const downloadProgressModal = container.querySelector('#download-progress-modal');

  // テーブルインデックス
  const operationHistoryIndex = tables.findIndex(t => t.tableName === '操作履歴') || 0;
  const groupIndex = tables.findIndex(t => t.tableName === '団体') || 1;
  const userIndex = tables.findIndex(t => t.tableName === '利用者') || 2;

  // 初期日付設定（過去30日）
  const today = new Date();
  const thirtyDaysAgo = new Date(today.getTime() - 30 * 24 * 60 * 60 * 1000);
  startDateInput.value = thirtyDaysAgo.toISOString().split('T')[0];
  endDateInput.value = today.toISOString().split('T')[0];

  // 団体リストを読み込む
  async function loadGroups() {
    const groups = await window.aivicApi.list(groupIndex);
    if (groups && groups.length > 0) {
      const options = groups.map(g => `<option value="${g.id}">${g.団体名}</option>`).join('');
      groupFilterSelect.innerHTML = '<option value="">すべて</option>' + options;
    }
  }

  // 利用者リストを読み込む
  async function loadUsers() {
    const users = await window.aivicApi.list(userIndex);
    if (users && users.length > 0) {
      window.usersCache = users;
    }
  }

  // 利用者検索
  userSearchInput.addEventListener('input', (e) => {
    const query = e.target.value.toLowerCase();
    if (!query) {
      userFilterSelect.innerHTML = '<option value="">検索結果がここに表示されます</option>';
      return;
    }
    const filtered = (window.usersCache || []).filter(u => 
      u.氏名.toLowerCase().includes(query) || u.メールアドレス.toLowerCase().includes(query)
    );
    const options = filtered.map(u => `<option value="${u.id}">${u.氏名} (${u.メールアドレス})</option>`).join('');
    userFilterSelect.innerHTML = options || '<option value="">該当する利用者がありません</option>';
  });

  // プレビューボタン
  previewButton.addEventListener('click', async () => {
    const reportType = container.querySelector('input[name="report-type"]:checked').value;
    const startDate = startDateInput.value;
    const endDate = endDateInput.value;
    const groups = Array.from(groupFilterSelect.selectedOptions).map(o => o.value).filter(v => v);
    const users = Array.from(userFilterSelect.selectedOptions).map(o => o.value);

    if (!startDate || !endDate) {
      alert('期間を指定してください');
      return;
    }

    // プレビュー内容を生成（ダミーデータ）
    let previewHtml = '';
    const reportTypeLabel = {
      reservation: '予約一覧',
      usage: '利用実績',
      billing: '料金計算結果',
      collection: '収納状況'
    }[reportType];

    previewHtml = `
      <div style="font-family: var(--font-family); color: var(--text);">
        <div style="text-align: center; margin-bottom: 20px; border-bottom: 2px solid var(--border); padding-bottom: 16px;">
          <div style="font-size: 18px; font-weight: 600; margin-bottom: 8px;">${reportTypeLabel}</div>
          <div style="font-size: 13px; color: var(--text-muted);">
            期間: ${startDate} ～ ${endDate}
          </div>
        </div>
        <table style="width: 100%; border-collapse: collapse; font-size: 13px;">
          <thead>
            <tr style="background: var(--table-header-bg); border-bottom: 1px solid var(--border);">
              <th style="padding: 10px; text-align: left; color: var(--text); font-weight: 600;">ID</th>
              <th style="padding: 10px; text-align: left; color: var(--text); font-weight: 600;">日時</th>
              <th style="padding: 10px; text-align: left; color: var(--text); font-weight: 600;">内容</th>
              <th style="padding: 10px; text-align: right; color: var(--text); font-weight: 600;">金額</th>
            </tr>
          </thead>
          <tbody>
            <tr style="border-bottom: 1px solid var(--border);">
              <td style="padding: 10px;">RES-001</td>
              <td style="padding: 10px;">2024-01-15</td>
              <td style="padding: 10px;">サンプルデータ</td>
              <td style="padding: 10px; text-align: right;">¥5,000</td>
            </tr>
            <tr style="border-bottom: 1px solid var(--border); background: var(--table-stripe-bg);">
              <td style="padding: 10px;">RES-002</td>
              <td style="padding: 10px;">2024-01-16</td>
              <td style="padding: 10px;">サンプルデータ</td>
              <td style="padding: 10px; text-align: right;">¥3,500</td>
            </tr>
          </tbody>
        </table>
        <div style="margin-top: 20px; padding-top: 16px; border-top: 1px solid var(--border); text-align: right; font-weight: 600;">
          合計: ¥8,500
        </div>
      </div>
    `;

    previewModalContent.innerHTML = previewHtml;
    previewModal.style.display = 'flex';
  });

  // プレビューモーダルを閉じる
  previewModalClose.addEventListener('click', () => {
    previewModal.style.display = 'none';
  });
  previewModal.addEventListener('click', (e) => {
    if (e.target === previewModal) {
      previewModal.style.display = 'none';
    }
  });

  // ダウンロードボタン
  downloadButton.addEventListener('click', async () => {
    const reportType = container.querySelector('input[name="report-type"]:checked').value;
    const exportFormat = container.querySelector('input[name="export-format"]:checked').value;
    const startDate = startDateInput.value;
    const endDate = endDateInput.value;

    if (!startDate || !endDate) {
      alert('期間を指定してください');
      return;
    }

    // ダウンロード進捗を表示
    downloadProgressModal.style.display = 'flex';
    downloadButton.disabled = true;

    // 進捗をシミュレート
    let progress = 0;
    const progressInterval = setInterval(() => {
      progress += Math.random() * 30;
      if (progress > 100) progress = 100;
      container.querySelector('#progress-bar').style.width = progress + '%';
      container.querySelector('#progress-text').textContent = Math.floor(progress) + '%';
    }, 200);

    // 操作履歴を記録
    setTimeout(async () => {
      clearInterval(progressInterval);
      container.querySelector('#progress-bar').style.width = '100%';
      container.querySelector('#progress-text').textContent = '100%';

      // 操作履歴を保存
      const historyRecord = {
        操作種別: 'ダウンロード',
        対象リソースタイプ: '帳票',
        操作内容: `${reportType} を ${exportFormat} 形式でダウンロード`,
        操作ステータス: '成功',
        実行開始日時: new Date().toISOString(),
        実行終了日時: new Date().toISOString()
      };
      await window.aivicApi.save(operationHistoryIndex, historyRecord);

      // ダウンロード実行（ダミー）
      const filename = `report_${reportType}_${new Date().getTime()}.${exportFormat === 'pdf' ? 'pdf' : exportFormat === 'excel' ? 'xlsx' : 'csv'}`;
      const link = document.createElement('a');
      link.href = 'data:text/plain,Sample Report Data';
      link.download = filename;
      link.click();

      setTimeout(() => {
        downloadProgressModal.style.display = 'none';
        downloadButton.disabled = false;
        loadOperationHistory();
      }, 500);
    }, 2000);
  });

  // リセットボタン
  resetButton.addEventListener('click', () => {
    const today = new Date();
    const thirtyDaysAgo = new Date(today.getTime() - 30 * 24 * 60 * 60 * 1000);
    startDateInput.value = thirtyDaysAgo.toISOString().split('T')[0];
    endDateInput.value = today.toISOString().split('T')[0];
    groupFilterSelect.value = '';
    userSearchInput.value = '';
    userFilterSelect.innerHTML = '<option value="">検索結果がここに表示されます</option>';
    reportTypeRadios[0].checked = true;
    exportFormatRadios[0].checked = true;
    previewArea.innerHTML = '<div><div style="font-size: 16px; font-weight: 600; color: var(--text); margin-bottom: 8px;">プレビュー</div><div style="color: var(--text-muted);">「プレビュー」ボタンをクリックして帳票を表示します</div></div>';
  });

  // 操作履歴を読み込む
  async function loadOperationHistory() {
    const history = await window.aivicApi.list(operationHistoryIndex);
    if (!history || history.length === 0) {
      historyTbody.innerHTML = '<tr style="border-bottom: 1px solid var(--border); background: var(--table-stripe-bg);"><td colspan="5" style="padding: 20px 8px; text-align: center; color: var(--text-muted);">履歴がありません</td></tr>';
      return;
    }

    const recentHistory = history.slice(-10).reverse();
    historyTbody.innerHTML = recentHistory.map((record, idx) => `
      <tr style="border-bottom: 1px solid var(--border); ${idx % 2 === 0 ? 'background: var(--table-stripe-bg);' : ''}">
        <td style="padding: 10px 8px; white-space: nowrap;">${new Date(record.実行開始日時).toLocaleString('ja-JP')}</td>
        <td style="padding: 10px 8px; white-space: nowrap;">${record.ユーザーID || 'システム'}</td>
        <td style="padding: 10px 8px; white-space: nowrap;">${record.操作内容 || '-'}</td>
        <td style="padding: 10px 8px; white-space: nowrap;">-</td>
        <td style="padding: 10px 8px; white-space: nowrap;">-</td>
      </tr>
    `).join('');
  }

  // 初期化
  loadGroups();
  loadUsers();
  loadOperationHistory();

  // Escキーでモーダルを閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      previewModal.style.display = 'none';
      downloadProgressModal.style.display = 'none';
    }
  });
}
